add('delivery-workflow','Systems','Isolated checkpoint delivery','Approved project workflow for high-quality, token-aware implementation without changing runtime behavior.','.loop/workflow.md:1; Loop/EFFICIENT-WORKFLOW.md:1; Loop/DELIVERY-WORKFLOW.md:1',[
 [['scope','Bounded approved checkpoint','Define objective, invariants, acceptance criteria, baseline, file ownership and exact checks. Tiny isolated changes may remain direct.']],
 [['mode','Automatic mode selection','Caveman → Focused → Isolated Autonomy → Ephemeral Specialists → High-Risk Gate. Escalate from evidence, not ceremony.']],
 [['ast','Task-scoped AST map','Map affected symbols, imports/callers, state owners, tests and atlas nodes. Keep parser indexes ephemeral and verify against source.']],
 [['context','Compact task packet','Load the active handoff, affected atlas/AST neighborhood and targeted source ranges; do not copy the full conversation or repeatedly scan history.']],
 [['sandbox','Task worktree + branch','Use isolation for substantial, risky, experimental or parallel work. One owner per shared integration hotspot.']],
 [['agents','Ephemeral specialists','Dispatch only independent high-value subtasks with minimal immutable packets; no recursive dispatch or external actions.']],
 [['diff','Unified diff handoff','Specialists return bounded diffs/findings; the primary agent reviews, applies and validates accepted hunks as sole integrator.']],
 [['tier','Automatic model tiering','Classify a marked bounded objective, not forbidden-action wording; use the least-cost capable route and record recommendation versus actual execution.']],
 [['implement','Focused implementation','Make one coherent checkpoint; use deterministic tools and targeted tests. Avoid duplicate agents and background overhead.']],
 [['review','Two-stage review','First requirements/scope; then correctness, maintainability, accessibility, security, performance and regression risk.']],
 [['sync','Atlas + handoff + checkpoint','Synchronize affected flows and continuity; run fresh applicable checks and record limitations.']],
 [['reset','Durable session reset','At a clean boundary, save baseline, decisions, owned symbols, evidence, risks and exact next action; start fresh instead of forking long history.']],
 [['pr','Focused pull request','Include only intended files, evidence, performance impact, manual checks and rollback boundary. External actions follow approval gates.']],
 [['merge','Approved integration merge','Merge into the integration branch, then fast-forward the local workspace without overwriting unrelated changes.']],
 [['regress','Combined regression gate','Exercise integrated behavior, localization, errors, atlas and relevant performance before release consideration.']],
 [['release','Separate production checkpoint','Production merge, push and deployment require their own review and authorization.']]
],[['scope','mode','Classify'],['mode','ast','Substantial'],['mode','context','Caveman / Focused'],['ast','context','Bound neighborhood'],['context','tier','Route'],['tier','sandbox','Isolate when needed'],['sandbox','agents','Independent work exists'],['sandbox','implement','Single owner'],['agents','diff','Return'],['diff','implement','Validate / apply'],['implement','review','Validate'],['review','implement','Fix findings'],['review','sync','Pass'],['sync','reset','Durable boundary'],['sync','pr','PR-ready'],['reset','scope','Fresh task'],['pr','merge','Approved'],['merge','regress','Synchronize local'],['regress','implement','Repair in owner branch'],['regress','release','Pass']],['Caveman Mode is deliberately primitive: smallest context, one direct agent, no sub-agents and the smallest deterministic check. A worktree consumes disk space, not model tokens. Effective savings come from bounded AST neighborhoods, unified diffs, fresh sessions, targeted checks, one owner and reduced rework. Assessment → modularization/loading → Cosmic Observatory remains the current feature order.']);

